 "content": "def transform(grid):
    # Encode anomalous marker crossings as pixels on the reduced lattice.
    h, w = len(grid), len(grid[0])
    marker_rows = [r for r, row in enumerate(grid) if row.count(9) >= 2]
    marker_cols = [c for c in range(w) if sum(grid[r][c] == 9 for r in range(h)) >= 2]
    out_h = min(3, len(marker_rows))
    out_w = 3
    out = [[1] * out_w for _ in range(out_h)]
    # The outer pair of vertical crossings map to the outer output cells;
    # the two inner crossings map to the middle cell.
    for y, r in enumerate(marker_rows[:out_h]):
        if grid[r][marker_cols[0]] == 9 or grid[r][marker_cols[1]] == 9:
            out[y][0] = 9
        if len(marker_cols) > 2 and (grid[r][marker_cols[1]] == 9 or grid[r][marker_cols[2]] == 9):
            out[y][1] = 9
        if len(marker_cols) > 3 and (grid[r][marker_cols[2]] == 9 or grid[r][marker_cols[3]] == 9):
            out[y][2] = 9
    return out
